```cpp
#include <iostream>
#include <fstream>
#include <queue>
using namespace std;

int main() {
    ifstream plik("siatka.txt");
    int m[6][6];
    for (int i = 0; i < 6; i++)
        for (int j = 0; j < 6; j++)
            plik >> m[i][j];
    int ones = 0;
    for (int i = 0; i < 6; i++)
        for (int j = 0; j < 6; j++)
            if (m[i][j] == 1) ones++;
    bool visited[6][6] = {};
    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};
    int comp = 0, maxSize = 0;
    for (int i = 0; i < 6; i++) {
        for (int j = 0; j < 6; j++) {
            if (m[i][j] == 1 && !visited[i][j]) {
                comp++;
                int size = 0;
                queue<pair<int,int>> q;
                q.push(make_pair(i, j));
                visited[i][j] = true;
                while (!q.empty()) {
                    int x = q.front().first;
                    int y = q.front().second;
                    q.pop();
                    size++;
                    for (int d = 0; d < 4; d++) {
                        int nx = x + dx[d];
                        int ny = y + dy[d];
                        if (nx >= 0 && nx < 6 && ny >= 0 && ny < 6 && m[nx][ny] == 1 && !visited[nx][ny]) {
                            visited[nx][ny] = true;
                            q.push(make_pair(nx, ny));
                        }
                    }
                }
                if (size > maxSize) maxSize = size;
            }
        }
    }
    cout << "Liczba jedynek: " << ones << endl;
    cout << "Liczba spojnych obszarow: " << comp << endl;
    cout << "Najwiekszy obszar: " << maxSize << endl;
    return 0;
}
```

Weryfikacja:
- Jedynki: 2+4+1+2+1+2 = 12
- Obszar 1: (0,0),(0,1),(1,0),(1,1),(1,2),(2,1) = 6
- Obszar 2: (1,4) = 1
- Obszar 3: (3,3),(3,4),(4,3) = 3
- Obszar 4: (5,0) = 1
- Obszar 5: (5,5) = 1
- Najwiekszy: 6
